"""Reconcile SENSE-02 native evidence, conditional RC arithmetic and archived viewer inputs."""
from pathlib import Path
import argparse,hashlib,json,math
import verify_candidate as verify
P=Path(__file__).resolve().parent;ROOT=P.parents[2]
FALSE=('hardware_accepted','fabrication_approved','procurement_approved','protection_qualified','qualification_ports_implemented','pcb_integrated')
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(n,t):(P/n).write_text(t if isinstance(t,str) else json.dumps(t,indent=2)+'\n',encoding='utf-8',newline='\n')
def filter_results():
    source=read(P/'sources.json');by_ref={ref:part for part in source['parts'] for ref in part['refs']}
    assert by_ref['R44']['MPN']=='RC0603FR-071KL' and by_ref['C37']['MPN']=='C1608X7R1H104K080AA' and by_ref['C59']['MPN']=='C1608X7R1E105K080AB'
    r=by_ref['R44']['value_ohm'];c=by_ref['C37']['value_F'];rt=by_ref['R44']['tolerance_fraction'];ct=by_ref['C37']['tolerance_fraction']
    assert (r,c,rt,ct)==(1000,1e-7,.01,.1)
    tau=r*c;lo=r*(1-rt)*c*(1-ct);hi=r*(1+rt)*c*(1+ct);step_log=14*math.log(2)
    return {'revision':'SENSE-02','classification':'ideal_RC_initial_tolerance_arithmetic_only','R44_ohm':r,'C37_nominal_F':c,'C59_nominal_F':by_ref['C59']['value_F'],'nominal_tau_s':tau,'initial_tolerance_tau_s':[lo,hi],'nominal_fc_Hz':1/(2*math.pi*tau),'initial_tolerance_fc_Hz':[1/(2*math.pi*hi),1/(2*math.pi*lo)],'ideal_12bit_fullscale_step_to_quarter_lsb_nominal_s':tau*step_log,'initial_tolerance_step_settling_s':[lo*step_log,hi*step_log],'actual_effective_C37_F':None,'actual_effective_C59_F':None,'actual_ADC_sample_cycles':None,'actual_ADC_clock_Hz':None,'amplifier_stability_qualified':False,'ADC_acquisition_qualified':False,'poweroff_protection_qualified':False,'pcb_layout_qualified':False,'hardware_accepted':False,'limitations':['Tolerance interval excludes DC bias, temperature, aging and frequency: not an effective-capacitance or system bound.','Ideal first-order step settling is not ADC track-and-hold acquisition or amplifier closed-loop response.','Nominal1uF does not prove effective bypass>=0.1uF at actual conditions or physical high-frequency performance.','No sample rate, current envelope, power-off protection, assembly or operating range released.']}
def outputs(v,a):
    d=v['candidate_electrical_delta'];e=v['native_erc'];s=v['source_preservation']
    lines=['# SENSE-02 — native delta and conditional filter results','','[Design guide](README.md) | [Native Power sheet](native/svg/LoRa_Boat_Controller_V2-Power.svg) | [Independent verification](validation.json) | [Manufacturer evidence](sources.json)','','## Recorded native correction','',f"KiCad 9.0.7 capture produced {d['components']} components, {d['physical_pin_memberships']} physical pin memberships, {d['nets']} nets and {d['sheets']} sheets. ERC reports {e['errors']} errors and {e['warnings']} inherited AD0 warning. This is captured native evidence, not a hardware result.",'','Independent comparison checks all 128 old component records under the declared three-reference field whitelist, preserves all 429 old node attributes and 428 unchanged pin memberships, and verifies exactly one moved old pin plus four new pins. Embedded symbols, sheet identities and all other complete net memberships are preserved.','', '| Pin | Baseline | Candidate |','|---|---|---|','| U8.1 | /ISENSE | /Power/ISENSE_DRV |','| R44.1 | Absent | /Power/ISENSE_DRV |','| R44.2 | Absent | /ISENSE |','| C59.1 | Absent | +3V3 |','| C59.2 | Absent | GND |','',f"Only Power.kicad_sch differs in the {s['source_files']}-file copy; {s['byte_identical_files']} files remain byte-identical, including both converters. ACT-01 population bytes and 580 prior input hashes remain unchanged. Live electrical/copper deltas are zero; no PCB, firmware or live BOM integration occurred.",'','## Filter arithmetic, not acceptance','','| Quantity | Nominal | Initial R/C tolerance only |','|---|---|---|',f"| R44/C37 time constant | {a['nominal_tau_s']*1e6:.3f} us | {a['initial_tolerance_tau_s'][0]*1e6:.3f}–{a['initial_tolerance_tau_s'][1]*1e6:.3f} us |",f"| Ideal single-pole cutoff | {a['nominal_fc_Hz']:.6f} Hz | {a['initial_tolerance_fc_Hz'][0]:.6f}–{a['initial_tolerance_fc_Hz'][1]:.6f} Hz |",f"| Ideal full-scale step to quarter-LSB at 12 bits | {a['ideal_12bit_fullscale_step_to_quarter_lsb_nominal_s']*1000:.6f} ms | {a['initial_tolerance_step_settling_s'][0]*1000:.6f}–{a['initial_tolerance_step_settling_s'][1]*1000:.6f} ms |",'','Equations: tau=R*C; fc=1/(2*pi*tau); ideal full-scale residual below 1/(4*2^12) requires tau*ln(2^14). The interval uses only initial resistor +/-1% and capacitor +/-10%. It excludes X7R bias, temperature, aging, frequency, amplifier impedance, trace parasitics and switched-capacitor acquisition. It is not a guaranteed system interval or sampling-rate choice.','','## Remaining acceptance gates','','Exact TDK/Yageo candidate identities are confirmed. C59 nominal1uF provides nominal margin over TI minimum0.1uF, but effective capacitance and physical high-frequency bypass remain unqualified. Existing0603 lands differ from TDK reflow recommendations; new components are not placed/routed on the PCB. R33 rating annotation grants no board-current increase.','','R44 is not a clamp or proven power-off protection. Divider reference/range, PA2/PA4 state-specific injection, INA18026V common-mode/transients, full6S feed, VSERVO and combinedIMU2 remain open. No ordering, assembly, flashing or powered-application release.','','Next: establish source and minimum-VDDA envelopes, then address divider scaling and power-off protection on a new isolated copy.','']
    return {'filter_analysis.json':json.dumps(a,indent=2)+'\n','RESULTS.md':'\n'.join(lines)}
def main():
    parser=argparse.ArgumentParser();g=parser.add_mutually_exclusive_group(required=True)
    for m in ('render','capture','check'):g.add_argument('--'+m,action='store_true')
    args=parser.parse_args();v=verify.collect();assert v==read(P/'validation.json'),'Stale independent native validation';a=filter_results()
    for n,t in outputs(v,a).items():
        if args.render:write(n,t)
        else:assert (P/n).read_text(encoding='utf-8')==t,'Stale calculated output: '+n
    if not args.render:
        for n,h in read(P/'review_notes.json')['reviewed_sha256'].items():assert sha(ROOT/n)==h,'Stale review: '+n
        aliases={'pm/index.template.html':P/'viewer-template.snapshot.html','pm/tools/build.mjs':P/'viewer-builder.snapshot.mjs'}
        for n,h in read(P/'viewer_check.json')['input_sha256'].items():assert sha(aliases.get(n,ROOT/n))==h,'Stale captured viewer input: '+n
        c=read(P/'expected_contract.json');m={'revision':'SENSE-02','source_revision':c['baseline_head'],'baseline_presentation':'POWER-DOC-01','candidate_electrical_delta':c['candidate_electrical_delta'],'live_electrical_delta':0,'live_copper_delta':0,'native_commands_rerun':True,'input_sha256':read(P/'input_manifest.json')['input_sha256'],'artifact_sha256':{f.relative_to(ROOT).as_posix():sha(f) for f in sorted(P.rglob('*')) if f.is_file() and f.name!='packet_manifest.json' and '__pycache__' not in f.parts},**{k:False for k in FALSE}}
        if args.capture:write('packet_manifest.json',m)
        else:assert read(P/'packet_manifest.json')==m,'Packet coverage/bytes changed'
    print('PASS SENSE-02 native declared delta and conditional RC replay; hardware held')
if __name__=='__main__':main()
